"""Private, evidence-based estimate comparison. No document intake endpoint."""
import re
import shutil
from editorial import write_editorial_page


def add(out, origin, pages):
    cards = ''
    for key, label in [('a', 'A'), ('b', 'B')]:
        cards += f'''<section class="sj-input" aria-labelledby="sj-title-{key}"><div class="sj-input-head"><h2 id="sj-title-{key}">Estimate {label}</h2><button type="button" class="sj-link sj-remove" id="sj-remove-{key}" aria-label="Remove estimate {label}">Remove</button></div><label class="sj-upload" for="sj-file-{key}">Choose a PDF<input id="sj-file-{key}" type="file" accept="application/pdf,.pdf" aria-describedby="sj-limits sj-status-{key} sj-warning-{key}"></label><details id="sj-paste-{key}"><summary>Or paste the estimate’s wording</summary><label class="sr-only" for="sj-text-{key}">Estimate {label} text</label><textarea id="sj-text-{key}" maxlength="150000" placeholder="Copy the scope, exclusions, warranty and payment terms…" spellcheck="false" autocomplete="off"></textarea></details><p class="sj-status" id="sj-status-{key}" role="status"></p><p class="sj-warning" id="sj-warning-{key}"></p></section>'''
    body = '''<div class="same-job wrap"><section class="sj-hero"><div><span class="sj-kicker">THE SAME JOB TEST</span><h1>Are these estimates for the same job?</h1><p class="sj-lead">Two prices tell you very little until you know what each one covers. Put the wording side by side and get the questions worth asking.</p><div class="sj-hero-actions"><a class="btn primary" href="#sj-workspace">Compare my estimates ↓</a><button type="button" id="sj-demo" class="sj-link">Try a fictional example →</button></div></div><div class="sj-art" aria-label="Illustration of two estimates with different thermostat work"><div class="sj-paper"><small>ESTIMATE A · ILLUSTRATION</small><p>Reconnect the <mark>existing thermostat.</mark></p></div><div class="sj-paper"><small>ESTIMATE B · ILLUSTRATION</small><p>Install a <mark>new thermostat.</mark></p></div><span class="sj-art-note">A small line can change the work you’re buying.</span></div></section><div class="sj-privacy-strip"><span>PDFs read on your device</span><span>No account or email needed</span><span>No business is contacted</span></div><p id="sj-working">Loading the comparison tool…</p><noscript><p>This tool needs JavaScript to read documents on your device. You can also use the <a href="/guides/compare-hvac-estimates/">estimate checklist</a> or <a href="/book/">contact a business</a>.</p></noscript><div id="sj-app" hidden><section class="sj-workspace" id="sj-workspace" aria-label="Your two estimates"><div class="sj-project"><label for="sj-trade">What kind of work?<select id="sj-trade"><option value="" selected>Choose the kind of work</option></select></label><button class="sj-link" type="button" id="sj-clear">Clear both estimates</button></div><div class="sj-inputs">''' + cards + '''</div><p id="sj-limits" class="sj-fine">Text-based PDFs only · Up to 10 MB and 25 pages each. Scans, photos and handwriting may not contain readable text. You can paste the wording instead.</p><div class="sj-compare-line"><button class="btn primary" id="sj-compare" type="button" disabled>Compare the wording →</button><span class="sj-fine">Keep the originals handy.</span></div></section><div class="sj-explainer"><div><h3>1. Read the wording</h3><p>Add two estimates for the same project. Files stay in this open page and are cleared when you leave or reload.</p></div><div><h3>2. Check the details</h3><p>See relevant passages and PDF page numbers. A mention doesn’t mean work is included; read the full terms.</p></div><div><h3>3. Ask better questions</h3><p>Choose the questions you want answered. Copy or save them, or review them before requesting local help.</p></div></div><section class="sj-results" id="sj-results" hidden aria-labelledby="sj-results-title"><p class="sj-demo-notice" id="sj-demo-notice" hidden>Fictional example. These businesses, equipment models and prices are not real offers.</p><span class="eyebrow">THE WORDING, SIDE BY SIDE</span><h2 id="sj-results-title" tabindex="-1">Here’s what to clarify.</h2><p class="sj-results-intro">These are keyword matches from the extracted text, not a full document review. “Mentioned in both” doesn’t mean the work or terms match. “Not found” doesn’t mean it’s excluded.</p><p class="sj-fine">Up to three passages are shown per topic. Check the complete estimates, attachments and any handwritten notes. This tool does not judge price, workmanship or code compliance.</p><nav class="sj-results-nav" aria-label="Comparison shortcuts"><a href="#sj-review" id="sj-review-link">Review your question sheet ↓</a><a href="#sj-workspace">Back to your estimates ↑</a></nav><div id="sj-rows"></div><section class="sj-review" id="sj-review" hidden><span class="eyebrow" id="sj-selected"></span><h2>Take these questions with you.</h2><p>Send them to the businesses that gave you the estimates. You can edit the list first.</p><label for="sj-notes">Your question sheet</label><textarea id="sj-notes" maxlength="2400" spellcheck="true"></textarea><div class="sj-actions"><button type="button" id="sj-copy" class="btn">Copy questions</button><button type="button" id="sj-download" class="btn">Save question sheet</button></div><p class="sj-fine">Only the text in this box is copied, saved or carried to the request form. The original PDFs and source excerpts are not attached.</p><button type="button" id="sj-help" class="btn primary">Review a request for local help →</button><p class="sj-fine">Next: review your questions, choose contact details and give permission to send. The next page accepts these notes for 10 minutes and removes them when opened.</p></section><p id="sj-message" role="status"></p></section></div><div class="sj-share"><button type="button" class="sj-link" id="sj-share">Know someone comparing estimates? Share this tool ↗</button><p class="sj-fine" id="sj-share-status" role="status">The shared link contains no estimate details.</p></div></div>'''
    write_editorial_page(out, origin, pages, '/same-job/', 'Compare Two Contractor Estimates', 'Compare contractor estimate wording privately on your device. See passages, check scope differences and make a question sheet before you book.', body)
    page = out/'same-job/index.html'
    content = page.read_text().replace('</head>', '<link rel="stylesheet" href="/assets/same-job.css"></head>', 1).replace('</body>', '<script type="module" src="/assets/same-job.mjs"></script></body>', 1)
    content = content.replace(' style="color:var(--orange)"', '')
    page.write_text(content)
    for name in ['same-job.css', 'same-job.mjs', 'same-job-core.mjs', 'same-job-pdf.mjs', 'estimate-handoff.mjs']:
        shutil.copy(out.parent/'assets'/name, out/'assets'/name)
    package = out.parent/'node_modules/pdfjs-dist'
    vendor = out/'assets/vendor/pdfjs-6.5.438'
    vendor.mkdir(parents=True, exist_ok=True)
    for name in ['pdf.min.mjs', 'pdf.worker.min.mjs']:
        shutil.copy(package/'legacy/build'/name, vendor/name)
    for name in ['cmaps', 'standard_fonts']:
        shutil.copytree(package/name, vendor/name, dirs_exist_ok=True)
    shutil.copy(package/'LICENSE', vendor/'LICENSE')
    home = out/'index.html'
    promo = '''<section class="wrap sj-home same-job-home" aria-labelledby="same-job-home-title"><div><span class="eyebrow">BEFORE YOU CHOOSE A PRICE</span><h2 id="same-job-home-title">Make sure you’re comparing the same work.</h2><p>Two estimates. Different details. See the wording side by side and leave with the questions worth asking.</p><a href="/same-job/" class="btn primary">Compare two estimates →</a><p class="sj-home-note">Free to use. PDFs stay on your device. No signup.</p></div><div class="sj-paper" aria-hidden="true"><small>A DETAIL WORTH ASKING ABOUT</small><p>A · Reconnect existing thermostat.</p><p>B · Install a new thermostat.</p><small>Same project. Different work.</small></div></section>'''
    content = home.read_text()
    match = re.search(r'<section[^>]*class="[^"]*network-intro[^"]*"', content)
    if not match: raise ValueError('Homepage placement for estimate comparison not found')
    content = content[:match.start()] + promo + content[match.start():]
    content = content.replace('</head>', '<link rel="stylesheet" href="/assets/same-job.css"></head>', 1)
    home.write_text(content)
    privacy = out/'privacy/index.html'
    content = privacy.read_text().replace('</main>', '<section class="wrap"><h2>The Same Job Test</h2><p>Estimate PDFs and pasted wording are read in your browser and are not uploaded to Wazoozie or an outside document service. They remain in the open page until you clear it, leave or reload. Document text is not added to analytics or shared links. Only after you choose to review a request are the question notes saved in this tab’s session storage. The request page accepts them for 10 minutes and removes them when opened. Unused notes may remain in the tab until it is closed; expired notes are rejected and removed when read. Nothing is sent until you review the form and consent to submission.</p></section></main>', 1)
    privacy.write_text(content)
    # Make the tool discoverable where a visitor is already reading about estimates.
    for path in ['compare', 'guides/compare-hvac-estimates', 'guides/painting-estimate-checklist', 'explore']:
        target = out/path/'index.html'
        content = target.read_text().replace('</main>', '<section class="wrap"><h2>Have two written estimates?</h2><p>Put the wording side by side and make a list of questions before you choose.</p><a class="btn" href="/same-job/">Compare two estimates →</a></section></main>', 1)
        target.write_text(content)
